-- Add the two owner-confirmed Coke SKUs and Skorch included-drink identities.
-- This portable, atomic operation only extends frozen reviewed JSON manifests.
-- Apply after the existing public-menu and included-drink-stock installations.
do $coke_public_manifest$
declare
  menu_hash text; stock_hash text;
  menu_acl aclitem[]; stock_acl aclitem[];
  v_tenant uuid;
begin
  perform set_config('lock_timeout','5s',true);
  perform set_config('statement_timeout','15s',true);
  if to_regnamespace('dishbee_private') is not null then
    raise exception 'mealdeck_coke_wrong_database'; end if;
  select business_id into v_tenant from mealdeck_private.installation
    where singleton and profile='mealdeck-independent-v1';
  if not found or v_tenant is null then
    raise exception 'mealdeck_coke_independent_profile_required'; end if;
  if current_user in ('anon','authenticated','service_role') or not exists(
    select 1 from pg_class where oid='mealdeck_private.installation'::regclass
      and pg_has_role(current_user,relowner,'USAGE')
  ) then raise exception 'mealdeck_coke_database_owner_required'; end if;

  select md5(prosrc),proacl into menu_hash,menu_acl from pg_proc
    where oid=to_regprocedure('mealdeck_private.public_menu_before_included_stock()')
      and prosecdef and proconfig @> array['search_path=""'];
  select md5(prosrc),proacl into stock_hash,stock_acl from pg_proc
    where oid=to_regprocedure('mealdeck_private.included_drink_stock_bindings(uuid)')
      and prosecdef and proconfig @> array['search_path=""'];
  if menu_hash is null or menu_hash not in
      ('dcc595a4592398e0a5949ca5aeb3354c','29ca45226d72512c1f21c38be46ee8f2')
    or stock_hash is null or stock_hash not in
      ('c0609f8515dcba6c8dde23e2f6e697cd','24f016f9c04e02c1db294147e2af6a79')
    or not exists(select 1 from pg_proc
      where oid=to_regprocedure('mealdeck_private.included_drink_stock_available(uuid,uuid,uuid)')
        and prosecdef and proconfig @> array['search_path=""']
        and md5(prosrc)='07147a0bfd0e85e7b3e219dcd60127cc')
    or not exists(select 1 from pg_proc
      where oid=to_regprocedure('public.mealdeck_public_menu()')
        and prosecdef and proconfig @> array['search_path=""']
        and md5(prosrc)='df46e674718f1a86455498298e9f48a1')
  then raise exception 'mealdeck_coke_reviewed_functions_required'; end if;
  if menu_hash='29ca45226d72512c1f21c38be46ee8f2'
    and stock_hash='24f016f9c04e02c1db294147e2af6a79' then return; end if;

  if menu_hash='dcc595a4592398e0a5949ca5aeb3354c' then
    execute $reviewed_menu_definition$
CREATE OR REPLACE FUNCTION mealdeck_private.public_menu_before_included_stock()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
