avo-chicken-grilled-chicken-wings-grilled-chicken-wings-price-variant-spicy-honey-bbq-8-pcs","allowed":true},{"id":"tavo-chicken-grilled-chicken-wings-grilled-chicken-wings-price-variant-dynamite-3-pcs","allowed":true},{"id":"tavo-chicken-grilled-chicken-wings-grilled-chicken-wings-price-variant-dynamite-5-pcs","allowed":true},{"id":"tavo-chicken-grilled-chicken-wings-grilled-chicken-wings-price-variant-dynamite-8-pcs","allowed":true},{"id":"tavo-chicken-grilled-chicken-wings-grilled-chicken-wings-price-variant-fiery-sweet-chilli-3-pcs","allowed":true},{"id":"tavo-chicken-grilled-chicken-wings-grilled-chicken-wings-price-variant-fiery-sweet-chilli-5-pcs","allowed":true},{"id":"tavo-chicken-grilled-chicken-wings-grilled-chicken-wings-price-variant-fiery-sweet-chilli-8-pcs","allowed":true}]},{"id":"skorch-burgers-burger-add-ons","options":[{"id":"skorch-burgers-burger-add-ons-2-rashers","allowed":true},{"id":"skorch-burgers-burger-add-ons-3-onion-rings","allowed":true},{"id":"skorch-burgers-burger-add-ons-cheese-slice","allowed":true}]},{"id":"skorch-burgers-make-it-a-meal","options":[{"id":"skorch-burgers-make-it-a-meal-make-it-a-meal","allowed":true}]},{"id":"skorch-burgers-meal-upgrades","options":[{"id":"skorch-burgers-meal-upgrades-peri-salt","allowed":true},{"id":"skorch-burgers-meal-upgrades-loaded-fries","allowed":true},{"id":"skorch-burgers-meal-upgrades-loaded-mac-n-cheese","allowed":true},{"id":"skorch-burgers-meal-upgrades-mocktail","allowed":true},{"id":"skorch-burgers-meal-upgrades-milkshake","allowed":false}]},{"id":"skorch-burgers-kids-meal-upgrades","options":[{"id":"skorch-burgers-kids-meal-upgrades-peri-salt","allowed":true},{"id":"skorch-burgers-kids-meal-upgrades-loaded-fries","allowed":true},{"id":"skorch-burgers-kids-meal-upgrades-loaded-mac-n-cheese","allowed":true},{"id":"skorch-burgers-kids-meal-upgrades-mocktail","allowed":true},{"id":"skorch-burgers-kids-meal-upgrades-milkshake","allowed":false}]},{"id":"skorch-burgers-included-meal-drink","options":[{"id":"skorch-burgers-included-meal-drink-pepsi","allowed":true},{"id":"skorch-burgers-included-meal-drink-pepsi-max","allowed":true},{"id":"skorch-burgers-included-meal-drink-tango-orange","allowed":true},{"id":"skorch-burgers-included-meal-drink-tango-apple","allowed":true},{"id":"skorch-burgers-included-meal-drink-rubicon-mango","allowed":true},{"id":"skorch-burgers-included-meal-drink-7up","allowed":true},{"id":"skorch-burgers-included-meal-drink-water-bottle","allowed":true},{"id":"skorch-burgers-included-meal-drink-coke","allowed":true}]},{"id":"skorch-burgers-kids-included-drink","options":[{"id":"skorch-burgers-kids-included-drink-pepsi","allowed":true},{"id":"skorch-burgers-kids-included-drink-pepsi-max","allowed":true},{"id":"skorch-burgers-kids-included-drink-tango-orange","allowed":true},{"id":"skorch-burgers-kids-included-drink-tango-apple","allowed":true},{"id":"skorch-burgers-kids-included-drink-rubicon-mango","allowed":true},{"id":"skorch-burgers-kids-included-drink-7up","allowed":true},{"id":"skorch-burgers-kids-included-drink-water-bottle","allowed":true},{"id":"skorch-burgers-kids-included-drink-coke","allowed":true}]},{"id":"souvano-donner-flavour","options":[{"id":"souvano-donner-flavour-plain","allowed":true},{"id":"souvano-donner-flavour-fiery-sweet-chilli","allowed":true},{"id":"souvano-donner-flavour-dynamite","allowed":true},{"id":"souvano-donner-flavour-korean-bbq","allowed":true}]},{"id":"souvano-heatwave-base","options":[{"id":"souvano-heatwave-base-fries","allowed":true},{"id":"souvano-heatwave-base-fragrant-spicy-rice","allowed":true},{"id":"souvano-heatwave-base-naan","allowed":true}]},{"id":"souvano-meal-side","options":[{"id":"souvano-meal-side-fries","allowed":true},{"id":"souvano-meal-side-rice","allowed":true},{"id":"souvano-meal-side-naan","allowed":true}]},{"id":"cross-side-replacement","options":[{"id":"cross-side-replacement-loadd-loaded-fries-king-of-hearts","allowed":true},{"id":"cross-side-replacement-loadd-loaded-fries-queen-of-hearts","allowed":true},{"id":"cross-side-replacement-loadd-loaded-fries-jack-of-diamonds","allowed":true},{"id":"cross-side-replacement-loadd-loaded-fries-king-of-spades","allowed":true},{"id":"cross-side-replacement-loadd-loaded-mac-cheese-ace-mac","allowed":true},{"id":"cross-side-replacement-loadd-loaded-mac-cheese-jacks-mac","allowed":true},{"id":"cross-side-replacement-loadd-loaded-mac-cheese-diamond-melt","allowed":true},{"id":"cross-side-replacement-loadd-loaded-mac-cheese-spade-stack","allowed":true},{"id":"cross-side-replacement-loadd-loaded-mac-cheese-kings-mac","allowed":true}]},{"id":"cross-drink-replacement","options":[{"id":"cross-drink-replacement-moktl-mocktail-lounge-virgin-mojito","allowed":true},{"id":"cross-drink-replacement-moktl-mocktail-lounge-mango-mirage","allowed":true},{"id":"cross-drink-replacement-moktl-mocktail-lounge-lychee-breeze","allowed":true},{"id":"cross-drink-replacement-moktl-mocktail-lounge-apple-rush","allowed":true},{"id":"cross-drink-replacement-moktl-mocktail-lounge-blue-wave","allowed":true},{"id":"cross-drink-replacement-moktl-mocktail-lounge-strawberry-splash","allowed":true},{"id":"cross-drink-replacement-moktl-mocktail-lounge-passion-paradise","allowed":true},{"id":"cross-drink-replacement-moktl-mocktail-lounge-rush-hour","allowed":true}]}]}'::jsonb;
begin
  select t.id,l.id into v_tenant,v_location
    from mealdeck_private.installation i
    join public.tenants t on t.id=i.business_id
    join public.tenant_locations l on l.tenant_id=t.id
    where i.singleton and i.profile='mealdeck-independent-v1'
      and i.bootstrap_owner_id is not null and i.bootstrapped_at is not null
      and t.active and t.slug='mealdeck' and t.legal_name='313 Brands Ltd' and t.currency='GBP'
      and l.slug='shared-kitchen' and l.active
      and (select count(*) from public.tenants)=1
      and (select count(*) from public.tenant_locations only_location
        where only_location.tenant_id=t.id and only_location.active)=1;
  if not found then raise exception 'mealdeck_public_menu_scope_unavailable'; end if;

  with source_items as materialized (
    select * from jsonb_to_recordset(v_source->'items')
      as s(sku text,brand text,groups jsonb,replacement jsonb)
  ), source_groups as materialized (
    select g->>'id' source_id,
      extensions.uuid_generate_v5(v_tenant,'mealdeck-launch-v1:group:'||(g->>'id')) group_id,
      g->'options' options
    from jsonb_array_elements(v_source->'groups') g
  ), source_options as materialized (
    select g.group_id,o->>'id' source_id,
      extensions.uuid_generate_v5(v_tenant,'mealdeck-launch-v1:option:'||(o->>'id')) option_id,
      (o->>'allowed')::boolean allowed
    from source_groups g cross join lateral jsonb_array_elements(g.options) o
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'sku',s.sku,'categoryName',c.name,'name',x.name,'description',nullif(x.description,''),
      'pricePence',coalesce(r.price_override_pence,x.price_pence),
      'options',coalesce((
        select jsonb_object_agg(so.source_id,jsonb_build_object(
          'label',o.name,'pricePence',o.price_delta_pence,'available',so.allowed and o.active
        ) order by so.source_id)
        from jsonb_array_elements_text(s.groups) item_group(source_id)
        join source_groups sg on sg.source_id=item_group.source_id
        join public.modifier_groups g on g.id=sg.group_id and g.tenant_id=v_tenant
        join public.menu_item_modifier_groups link on link.group_id=g.id
          and link.tenant_id=g.tenant_id and link.item_id=x.id
        join source_options so on so.group_id=g.id
        join public.modifier_options o on o.id=so.option_id
          and o.group_id=g.id and o.tenant_id=g.tenant_id
        where length(btrim(o.name)) between 1 and 140
          and o.price_delta_pence between 0 and 1000000
      ),'{}'::jsonb),
      'replacementPricePence',case when replacement.active then replacement.price_delta_pence else null end
    ) || case when replacement.id is null then '{}'::jsonb
      else jsonb_build_object('replacementLabel',replacement.name) end
    order by s.sku
  ),'[]'::jsonb) into v_items
  from source_items s
  join public.menu_items x on x.sku=s.sku and x.tenant_id=v_tenant
  join public.tenant_brands b on b.id=x.brand_id and b.tenant_id=x.tenant_id and b.slug=s.brand
  join public.menu_categories c on c.id=x.category_id and c.tenant_id=x.tenant_id and c.brand_id=x.brand_id
  join public.menu_item_channel_rules r on r.menu_item_id=x.id and r.tenant_id=x.tenant_id
    and r.location_id=v_location and r.channel_key='mealdeck'
  left join lateral (
    select o.id,o.name,o.price_delta_pence,o.active
      from source_groups sg join source_options so on so.group_id=sg.group_id
      join public.modifier_groups g on g.id=sg.group_id and g.tenant_id=v_tenant
      join public.modifier_options o on o.id=so.option_id and o.group_id=g.id and o.tenant_id=g.tenant_id
      where sg.source_id=s.replacement->>'group' and so.source_id=s.replacement->>'option'
        and so.allowed and length(btrim(o.name)) between 1 and 140
        and o.price_delta_pence between 0 and 1000000
  ) replacement on true
  where x.active and b.active and c.active and r.visible
    and length(btrim(x.name)) between 1 and 140 and length(btrim(c.name)) between 1 and 140
    and coalesce(length(x.description),0)<=2000
    and coalesce(r.price_override_pence,x.price_pence) between 0 and 1000000
    and (select count(*) from public.menu_items duplicate
      where duplicate.tenant_id=v_tenant and duplicate.sku=x.sku)=1
    and exists(select 1 from public.menu_item_station_routes route
      join public.kitchen_stations station on station.id=route.station_id
        and station.tenant_id=route.tenant_id and station.location_id=route.location_id and station.active
      where route.tenant_id=v_tenant and route.location_id=v_location and route.item_id=x.id)
    -- New required groups cannot silently disappear from the reviewed customer form.
    and not exists(select 1 from public.menu_item_modifier_groups required_link
      join public.modifier_groups required_group on required_group.id=required_link.group_id
        and required_group.tenant_id=required_link.tenant_id
      where required_link.tenant_id=v_tenant and required_link.item_id=x.id and required_group.min_select>0
        and not exists(select 1 from jsonb_array_elements_text(s.groups) known(source_id)
          join source_groups sg on sg.source_id=known.source_id where sg.group_id=required_group.id));

  return jsonb_build_object('available',true,'checkedAt',now(),'items',v_items);
end
$function$
$reviewed_menu_definition$;
  end if;
  if stock_hash='c0609f8515dcba6c8dde23e2f6e697cd' then
    execute $reviewed_stock_definition$
CREATE OR REPLACE FUNCTION mealdeck_private.included_drink_stock_bindings(p_tenant uuid)
 RETURNS TABLE(option_id uuid, group_id uuid, source_option_id text, brand_slug text, target_sku text)
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select extensions.uuid_generate_v5(p_tenant,'mealdeck-launch-v1:option:'||(b->>'option')),
    extensions.uuid_generate_v5(p_tenant,'mealdeck-launch-v1:group:'||(b->>'group')),
    b->>'option',b->>'brand',b->>'sku'
  from jsonb_array_elements(('{"version":1,"bindings":[{"option":"tavo-chicken-included-meal-drink-coke","group":"tavo-chicken-included-meal-drink","sku":"tavo-chicken-cans-drinks-coke","brand":"tavo-chicken"},{"option":"tavo-chicken-included-meal-drink-pepsi-max","group":"tavo-chicken-included-meal-drink","sku":"tavo-chicken-cans-drinks-pepsi-max","brand":"tavo-chicken"},{"option":"tavo-chicken-included-meal-drink-tango-apple","group":"tavo-chicken-included-meal-drink","sku":"tavo-chicken-cans-drinks-tango-apple","brand":"tavo-chicken"},{"option":"tavo-chicken-included-meal-drink-miranda-orange","group":"tavo-chicken-included-meal-drink","sku":"tavo-chicken-cans-drinks-miranda-orange","brand":"tavo-chicken"},{"option":"tavo-chicken-included-meal-drink-miranda-strawberry","group":"tavo-chicken-included-meal-drink","sku":"tavo-chicken-cans-drinks-miranda-strawberry","brand":"tavo-chicken"},{"option":"tavo-chicken-included-meal-drink-barr-limeade","group":"tavo-chicken-included-meal-drink","sku":"tavo-chicken-cans-drinks-barr-limeade","brand":"tavo-chicken"},{"option":"tavo-chicken-included-meal-drink-water-bottle","group":"tavo-chicken-included-meal-drink","sku":"tavo-chicken-cans-drinks-water-bottle","brand":"tavo-chicken"},{"option":"tavo-chicken-kids-included-drink-coke","group":"tavo-chicken-kids-included-drink","sku":"tavo-chicken-cans-drinks-coke","brand":"tavo-chicken"},{"option":"tavo-chicken-kids-included-drink-pepsi-max","group":"tavo-chicken-kids-included-drink","sku":"tavo-chicken-cans-drinks-pepsi-max","brand":"tavo-chicken"},{"option":"tavo-chicken-kids-included-drink-tango-apple","group":"tavo-chicken-kids-included-drink","sku":"tavo-chicken-cans-drinks-tango-apple","brand":"tavo-chicken"},{"option":"tavo-chicken-kids-included-drink-miranda-orange","group":"tavo-chicken-kids-included-drink","sku":"tavo-chicken-cans-drinks-miranda-orange","brand":"tavo-chicken"},{"option":"tavo-chicken-kids-included-drink-miranda-strawberry","group":"tavo-chicken-kids-included-drink","sku":"tavo-chicken-cans-drinks-miranda-strawberry","brand":"tavo-chicken"},{"option":"tavo-chicken-kids-included-drink-barr-limeade","group":"tavo-chicken-kids-included-drink","sku":"tavo-chicken-cans-drinks-barr-limeade","brand":"tavo-chicken"},{"option":"tavo-chicken-kids-included-drink-water-bottle","group":"tavo-chicken-kids-included-drink","sku":"tavo-chicken-cans-drinks-water-bottle","brand":"tavo-chicken"},{"option":"skorch-burgers-included-meal-drink-pepsi","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-pepsi","brand":"skorch-burgers"},{"option":"skorch-burgers-included-meal-drink-pepsi-max","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-pepsi-max","brand":"skorch-burgers"},{"option":"skorch-burgers-included-meal-drink-tango-orange","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-tango-orange","brand":"skorch-burgers"},{"option":"skorch-burgers-included-meal-drink-tango-apple","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-tango-apple","brand":"skorch-burgers"},{"option":"skorch-burgers-included-meal-drink-rubicon-mango","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-rubicon-mango","brand":"skorch-burgers"},{"option":"skorch-burgers-included-meal-drink-7up","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-7up","brand":"skorch-burgers"},{"option":"skorch-burgers-included-meal-drink-water-bottle","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-water-bottle","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-pepsi","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-pepsi","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-pepsi-max","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-pepsi-max","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-tango-orange","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-tango-orange","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-tango-apple","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-tango-apple","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-rubicon-mango","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-rubicon-mango","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-7up","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-7up","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-water-bottle","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-water-bottle","brand":"skorch-burgers"},{"option":"skorch-burgers-included-meal-drink-coke","group":"skorch-burgers-included-meal-drink","sku":"skorch-burgers-cans-drinks-coke","brand":"skorch-burgers"},{"option":"skorch-burgers-kids-included-drink-coke","group":"skorch-burgers-kids-included-drink","sku":"skorch-burgers-cans-drinks-coke","brand":"skorch-burgers"}]}'::jsonb)->'bindings') b
$function$
$reviewed_stock_definition$;
  end if;

  if not exists(select 1 from pg_proc
      where oid=to_regprocedure('mealdeck_private.public_menu_before_included_stock()')
        and md5(prosrc)='29ca45226d72512c1f21c38be46ee8f2'
        and proacl is not distinct from menu_acl
        and prosecdef and proconfig @> array['search_path=""'])
    or not exists(select 1 from pg_proc
      where oid=to_regprocedure('mealdeck_private.included_drink_stock_bindings(uuid)')
        and md5(prosrc)='24f016f9c04e02c1db294147e2af6a79'
        and proacl is not distinct from stock_acl
        and prosecdef and proconfig @> array['search_path=""'])
    or (select count(*) from mealdeck_private.included_drink_stock_bindings(v_tenant))<>30
  then raise exception 'mealdeck_coke_manifest_verification_failed'; end if;

  insert into public.mealdeck_ops_audit_log(
    tenant_id,location_id,actor_id,action,entity_type,entity_id,previous_value,next_value
  ) values(
    v_tenant,null,null,'catalogue.coke_manifest','catalogue',v_tenant,
    jsonb_build_object('publicMenuBodyMd5',menu_hash,'stockBindingsBodyMd5',stock_hash),
    jsonb_build_object(
